package edu.riara.edp.week08;
import javafx.application.Application;import javafx.beans.property.*;import javafx.scene.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Stage;public class TwoWayBindingDemo extends Application {public void start(Stage s){StringProperty shared=new SimpleStringProperty("Change either field");TextField first=new TextField(),second=new TextField();first.textProperty().bindBidirectional(shared);second.textProperty().bindBidirectional(shared);s.setScene(new Scene(new VBox(12,first,second),400,160));s.show();}public static void main(String[]a){launch(a);}}